{
  "name": "@genspark/opencode-conversation-archiver",
  "version": "0.4.0",
  "description": "Archive OpenCode and GenCode (1.x and 2.x) conversations as readable Markdown in a git repository",
  "keywords": [
    "opencode",
    "conversation",
    "archive",
    "git",
    "genspark"
  ],
  "author": "Genspark",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/wework5119/gen-spark.git",
    "directory": "toolkits/opencode-conversation-archiver"
  },
  "homepage": "https://github.com/wework5119/gen-spark/tree/main/toolkits/opencode-conversation-archiver#readme",
  "bugs": {
    "url": "https://github.com/wework5119/gen-spark/issues"
  },
  "type": "module",
  "main": "./dist/server.js",
  "exports": {
    ".": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js"
    },
    "./server": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js",
      "config": {
        "mode": "auto"
      }
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "USER_GUIDE.md"
  ],
  "bin": {
    "opencode-conversation-archiver": "./dist/cli.js"
  },
  "scripts": {
    "build": "tsc",
    "lint": "tsc --noEmit",
    "test": "vitest run",
    "typecheck": "tsc --noEmit",
    "pack:dry-run": "npm pack --dry-run",
    "prepublishOnly": "npm run lint && npm test && npm run build"
  },
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=20.0.0",
    "opencode": ">=1.17.18 <2"
  },
  "overrides": {
    "effect": {
      "toml": "^5.0.1"
    },
    "zod": "^4.6.6"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.17.18",
    "@opencode/plugin": "^2.2.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opencode/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.17.18",
    "@opencode-ai/sdk": "1.17.18",
    "@opencode/plugin": "2.2.1",
    "@types/bun": "latest",
    "typescript": "^5.8.2",
    "vitest": "^4.1.12"
  }
}
